import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static int K;
    static long N;
    static class Matrix {
        int[][] m = new int[31][31];

        Matrix() {
            for (int i = 0; i <= K; i++) {
                for (int j = 0; j <= K; j++) {
                    m[i][j] = 0;
                }
            }
        }

        Matrix multiply(Matrix other) {
            Matrix result = new Matrix();
            for (int i = 0; i <= K; i++) {
                for (int j = 0; j <= K; j++) {
                    long sum = 0;
                    for (int k = 0; k <= K; k++) {
                        sum += (long) m[i][k] * other.m[k][j];
                    }
                    result.m[i][j] = (int) (sum % MOD);
                }
            }
            return result;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
        K = sc.nextInt();

        // Extract base digits
        int[] baseDigits = new int[65];
        int size = 0;
        long tempN = N;
        while (tempN > 0) {
            baseDigits[size++] = (int) (tempN % K);
            tempN /= K;
        }

        // Initialize matrices A[0][i]
        Matrix[][] A = new Matrix[65][30];
        Matrix[][] P = new Matrix[65][30];
        Matrix[][] S = new Matrix[65][30];

        for (int i = 0; i < 65; i++) {
            for (int j = 0; j < 30; j++) {
                A[i][j] = new Matrix();
                P[i][j] = new Matrix();
                S[i][j] = new Matrix();
            }
        }

        // Build initial matrices
        for (int i = 0; i < K; i++) {
            for (int j = 0; j <= K; j++) {
                A[0][i].m[j][j] = 1;
            }
            for (int j = 0; j <= K; j++) {
                A[0][i].m[i][j] = 1;
            }
        }

        // Build matrices for each digit
        for (int i = 1; i < size; i++) {
            // P[i-1][0] = A[i-1][0]
            P[i - 1][0] = A[i - 1][0];

            // P[i-1][j] = P[i-1][j-1] * A[i-1][j]
            for (int j = 1; j < K; j++) {
                P[i - 1][j] = P[i - 1][j - 1].multiply(A[i - 1][j]);
            }

            // S[i-1][K-1] = A[i-1][K-1]
            S[i - 1][K - 1] = A[i - 1][K - 1];

            // S[i-1][j] = A[i-1][j] * S[i-1][j+1]
            for (int j = K - 2; j >= 0; j--) {
                S[i - 1][j] = A[i - 1][j].multiply(S[i - 1][j + 1]);
            }

            // A[i][j]
            for (int j = 0; j < K; j++) {
                A[i][j] = S[i - 1][j];
                if (j > 0) {
                    A[i][j] = A[i][j].multiply(P[i - 1][j - 1]);
                }
            }
        }

        // Initialize result matrix res
        Matrix res = new Matrix();
        for (int i = 0; i <= K; i++) {
            res.m[i][i] = 1;
        }

        int x = 0;
        for (int i = size - 1; i >= 0; i--) {
            int digit = baseDigits[i];
            for (int j = 0; j < digit; j++) {
                res = res.multiply(A[i][x]);
                x = (x + 1) % K;
            }
        }

        int answer = 0;
        for (int i = 0; i <= K; i++) {
            answer = (answer + res.m[i][K]) % MOD;
        }

        System.out.println(answer);
        sc.close();
    }
}
